// Keep only invoices that actually need chasing today.
const settings = $('Business Settings').first().json;
const today = new Date();
today.setHours(0, 0, 0, 0);
const rows = $input.all();
const out = [];

for (const item of rows) {
  const row = item.json;
  const status = String(row['Status'] || '').trim().toLowerCase();
  // Never chase settled or excluded invoices
  if (['paid', 'void', 'draft', 'written off', 'do not chase'].includes(status)) continue;

  const invoiceId = String(row['Invoice ID'] || '').trim();
  const email = String(row['Client Email'] || '').trim();
  const amount = String(row['Amount'] || '').trim();
  const dueRaw = row['Due Date'];
  // Skip malformed rows instead of crashing the whole run
  if (!invoiceId || !email.includes('@') || !amount || !dueRaw) continue;

  const due = new Date(dueRaw);
  if (isNaN(due.getTime())) continue;
  due.setHours(0, 0, 0, 0);

  const daysOverdue = Math.floor((today.getTime() - due.getTime()) / 86400000);
  if (daysOverdue < 3) continue; // not overdue enough yet

  let stage = 'friendly';
  if (daysOverdue >= 30) stage = 'final';
  else if (daysOverdue >= 14) stage = 'firm';

  // Each tier fires exactly once per invoice - the sheet remembers the last stage sent.
  const lastStage = String(row['Last Reminder Stage'] || '').trim().toLowerCase();
  if (lastStage === stage) continue;

  out.push({
    json: {
      invoice_id: invoiceId,
      client_name: String(row['Client Name'] || 'there').trim(),
      client_email: email,
      amount: amount,
      currency: String(row['Currency'] || 'USD').trim(),
      due_date: due.toISOString().slice(0, 10),
      days_overdue: daysOverdue,
      stage: stage,
      next_chase_count: (parseInt(row['Chase Count'], 10) || 0) + 1,
      today: new Date().toISOString().slice(0, 10),
      business_name: settings.business_name || '',
      sender_name: settings.sender_name || '',
      payment_link: settings.payment_link || ''
    }
  });
}

if (out.length === 0) {
  return [{ json: { nothing_to_chase: true, rows_checked: rows.length, message: 'No invoices need chasing today.' } }];
}
return out;

// Safely parse the AI response. If the call failed or returned bad JSON,
// fall back to a clean built-in template so the reminder still goes out.
const invoice = $('Loop Invoices').first().json;
const resp = $input.first().json;

let raw = '';
if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) {
  raw = String(resp.choices[0].message.content || '');
}

let subject = '';
let body = '';
let aiOk = false;

if (raw) {
  let text = raw.trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) { text = fence[1].trim(); }
  try {
    const parsed = JSON.parse(text);
    if (parsed && parsed.subject && parsed.body) {
      subject = String(parsed.subject).trim();
      body = String(parsed.body).trim();
      aiOk = true;
    }
  } catch (e) {
    // fall through to the template below
  }
}

if (!aiOk) {
  const labels = { friendly: 'Friendly reminder', firm: 'Overdue notice', final: 'Final notice' };
  subject = (labels[invoice.stage] || 'Payment reminder') + ' - invoice ' + invoice.invoice_id;
  body = 'Hi ' + invoice.client_name + ',\n\n'
    + 'Our records show invoice ' + invoice.invoice_id + ' for ' + invoice.currency + ' ' + invoice.amount
    + ', due on ' + invoice.due_date + ', is still open (' + invoice.days_overdue + ' days past due).\n\n'
    + 'Could you arrange payment at your earliest convenience?'
    + (invoice.payment_link ? ' You can pay securely here: ' + invoice.payment_link : '')
    + '\n\nThank you,\n' + invoice.sender_name + '\n' + invoice.business_name;
}

return [{ json: Object.assign({}, invoice, { email_subject: subject, email_body: body, ai_generated: aiOk }) }];
